import type { MetadataRoute } from "next";
import { ALL_SLUGS } from "./docs/content/index";
import lastmod from "./lastmod.json";

const BASE = "https://lacy.sh";

// Generated by `npm run lastmod` from git history. Do not hand-edit the dates:
// the previous hardcoded values drifted five months behind the real edits, which
// told Google the whole docs section had been untouched since May.
const DATES: Record<string, string> = lastmod;

// Oldest real commit in the repo. Only used if a page has no recorded date,
// which means someone added a route without rerunning the generator.
const FALLBACK = "2026-05-11";

function modified(...sources: string[]): string {
  const dates = sources.map((s) => DATES[s]).filter(Boolean);
  return dates.length ? dates.sort().at(-1)! : FALLBACK;
}

// Author dates shown in each article. Update when a new post is published.
const BLOG_PUBLISH_DATES: Record<string, string> = {
  "why-i-didnt-use-ai-to-classify-ai-input": "2026-05-12",
  "shell-reserved-words-are-trickier-than-they-look": "2026-05-19",
  "the-post-execution-reroute-pattern": "2026-05-26",
};

const VS_SLUGS = [
  "warp",
  "shell-gpt",
  "github-copilot-cli",
  "aider",
  "cursor",
  "ai-shell",
  "amazon-q",
];

const TOOL_SLUGS = ["claude", "opencode", "gemini"];

export default function sitemap(): MetadataRoute.Sitemap {
  // A doc's rendered page is the content module plus the shared [slug] route.
  const docPages: MetadataRoute.Sitemap = ALL_SLUGS.map((slug) => ({
    url: `${BASE}/docs/${slug}`,
    lastModified: modified(
      `app/docs/content/${slug}.tsx`,
      "app/docs/[slug]/page.tsx"
    ),
    changeFrequency: "monthly" as const,
    priority: slug === "introduction" || slug === "installation" ? 0.9 : 0.8,
  }));

  const vsPages: MetadataRoute.Sitemap = VS_SLUGS.map((slug) => ({
    url: `${BASE}/vs/${slug}`,
    lastModified: modified(`app/vs/${slug}/page.tsx`),
    changeFrequency: "monthly" as const,
    priority: 0.7,
  }));

  const toolPages: MetadataRoute.Sitemap = TOOL_SLUGS.map((slug) => ({
    url: `${BASE}/tools/${slug}`,
    lastModified: modified(`app/tools/${slug}/page.tsx`),
    changeFrequency: "monthly" as const,
    priority: 0.7,
  }));

  // A post is never older than the day it went out, however late it was committed.
  const blogPostPages: MetadataRoute.Sitemap = Object.entries(
    BLOG_PUBLISH_DATES
  ).map(([slug, published]) => ({
    url: `${BASE}/blog/${slug}`,
    lastModified: [modified(`app/blog/${slug}/page.tsx`), published]
      .sort()
      .at(-1)!,
    changeFrequency: "monthly" as const,
    priority: 0.8,
  }));

  const newestBlogDate = blogPostPages
    .map((p) => String(p.lastModified))
    .sort()
    .at(-1)!;

  return [
    {
      url: BASE,
      lastModified: modified("app/page.tsx"),
      changeFrequency: "weekly",
      priority: 1.0,
    },
    {
      url: `${BASE}/vs`,
      lastModified: modified("app/vs/page.tsx"),
      changeFrequency: "monthly",
      priority: 0.7,
    },
    ...vsPages,
    {
      url: `${BASE}/blog`,
      lastModified: [modified("app/blog/page.tsx"), newestBlogDate]
        .sort()
        .at(-1)!,
      changeFrequency: "weekly",
      priority: 0.8,
    },
    ...blogPostPages,
    {
      url: `${BASE}/tools`,
      lastModified: modified("app/tools/page.tsx"),
      changeFrequency: "monthly",
      priority: 0.7,
    },
    ...toolPages,
    ...docPages,
    {
      url: `${BASE}/privacy`,
      lastModified: modified("app/privacy/page.tsx"),
      changeFrequency: "yearly",
      priority: 0.3,
    },
  ];
}
